head.script:
scwin.count1 = 0;
scwin.count2 = 0;
scwin.count3 = 0;
scwin.trigger1_onclick = function (e) {
	scwin.count1++;
	widgetContainer1.addWidgets({
		id: "widget" + scwin.count1,
		title: "위젯" + scwin.count1,
		src: "/sample/common_link/widgetContainer_widget_addWidgets_fixed_icon_WESD-1001_(WSQ-4988)_widget.xml",
		scope: true,
		fixed: true,
		x: 1,
		y: 1,
		unitWidth: 1,
		unitHeight: 1
	});
};
scwin.trigger2_onclick = function (e) {
	scwin.count2++;
	widgetContainer2.addWidgets({
		id: "widget" + scwin.count2,
		title: "위젯" + scwin.count2,
		src: "/sample/common_link/widgetContainer_widget_addWidgets_fixed_icon_WESD-1001_(WSQ-4988)_widget.xml",
		scope: true,
		fixed: true,
		x: 0,
		y: 1,
		unitWidth: 1,
		unitHeight: 1
	});
};
scwin.trigger3_onclick = function (e) {
	scwin.count3++;
	widgetContainer1.addWidgets({
		id: "plain" + scwin.count3,
		title: "위젯" + scwin.count3,
		src: "/sample/common_link/widgetContainer_widget_addWidgets_fixed_icon_WESD-1001_(WSQ-4988)_widget.xml",
		scope: true,
		x: 2,
		y: 1,
		unitWidth: 1,
		unitHeight: 1
	});
};
